import { Component, effect, inject, signal, untracked } from '@angular/core';
import { Session, otherError } from '../../core/session';
import { PolicyVersion, SettingsApi } from './settings-api';

// The sheet's policy versions, shown on request: one line per version, oldest first, as its number,
// its from-date (or "start" when it has none), the setting it changed as key=value, and how many
// claims it is the policy version of.
@Component({
  selector: 'app-policy-versions',
  template: `
    <button type="button" data-testid="policy-show" (click)="show()">Show policy versions</button>
    @if (error()) {
      <p role="alert" data-testid="policy-error">{{ error() }}</p>
    }
    @if (versions().length > 0) {
      <ol aria-label="Policy versions">
        @for (v of versions(); track v.number) {
          <li data-testid="policy-line">{{ v.number }} {{ v.from ?? 'start' }} {{ v.key }}={{ v.value }} {{ v.claims }}</li>
        }
      </ol>
    }
  `,
})
export class PolicyVersions {
  private readonly session = inject(Session);
  private readonly api = inject(SettingsApi);

  protected readonly versions = signal<PolicyVersion[]>([]);
  protected readonly error = signal<string | null>(null);

  constructor() {
    effect(() => {
      this.session.sheetId();
      this.session.loads();
      untracked(() => {
        this.versions.set([]);
        this.error.set(null);
      });
    });
  }

  protected async show(): Promise<void> {
    const id = this.session.sheetId();
    this.versions.set([]);
    this.error.set(null);
    if (!id) return;
    try {
      this.versions.set(await this.api.policyVersions(id));
    } catch (e) {
      this.error.set(otherError(e));
    }
  }
}
        return versions.stream().map(PolicyVersion::getFrom).toList();
    }

    /** A version of the sheet's policy as the screen lists it: its number, its from-date (null:
     *  none, counted on every date), the key of the setting its change set and the value it set
     *  (blank: none), and how many of the sheet's claims (DELETED ones left out) it is the policy
     *  version of. */
    public record PolicyVersionView(int number, LocalDate from, String key, String value, long claims) {
        static List<PolicyVersionView> of(List<PolicyVersion> versions, Map<Integer, Long> claims) {
            return versions.stream().map(v -> new PolicyVersionView(v.getNumber(), v.getFrom(), v.getKey(),
                    v.getValue() == null ? "" : v.getValue(), claims.getOrDefault(v.getNumber(), 0L))).toList();
        }
    }

    /** A value recorded for a dated setting: in force from its from-date until the next one of its
     *  key; null for none. */
    public record DatedValue(LocalDate from, String value) {
        /** Every value recorded, by key, each key's by from-date. */
        public static Map<String, List<DatedValue>> of(Map<String, List<DatedSetting>> dated) {
            Map<String, List<DatedValue>> out = new TreeMap<>();
            dated.forEach((key, values) -> out.put(key,
    public SettingsView settings(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user,
            @RequestHeader(value = AsOfGuard.HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate asOf) {
        return asOf == null ? view(sheetId) : viewAsOf(history.asOf(sheetId, asOf));
    }

    /** Every version of the sheet's policy, oldest first, with how many claims each is the policy
